black.main:
QWidget { font: 10pt "Arial"; color: #ffffff; }
QMainWindow { background-color: rgb(33, 33, 33); color: rgb(33, 33, 33); }
QMenu {
    background-color: #2b2b2b;
    color: #ffffff;
    border: 1px solid #555555;
    border-radius: 10px;
    padding: 5px;
}
QMenu::item:selected, QMenu::item:hover, QMenuBar::item:selected, QToolButton:hover {
    background: rgb(40, 40, 40);
    color: rgb(240, 240, 240);
    font: 10pt "Arial";
}
QMenu::item:disabled { color: #666666; background-color: transparent; }
QMenuBar {
    background-color: #2b2b2b;
    color: #ffffff;
    font-size: 10px;
    padding: 4px;
    border-bottom: 1px solid #3c3c3c;
}
QPushButton {
    border: 1px solid #555555;
    border-radius: 5px;
    background-color: #353535;
    color: #ffffff;
    font: 10pt "Arial";
}
QPushButton:hover {
    border: 1px solid rgb(40, 40, 40);
    border-radius: 5px;
    background-color: rgb(40, 40, 40);
    color: rgb(240, 240, 240);
    font: 10pt "Arial";
}
QPushButton:disabled { color: #777777; background-color: #303030; border: 1px solid #444444; }
QTextEdit {
    background-color: #2b2b2b;
    border: 2px solid #555555;
    border-radius: 15px;
    font: 10pt "Arial";
    color: rgb(255, 255, 255);
}
QListWidget {
    background-color: #2b2b2b;
    border: 2px solid #555555;
    border-radius: 15px;
    font: 10pt "Arial";
    color: rgb(255, 255, 255);
}
QLabel { color: #ffffff; font: 10pt "Arial"; }
QStatusBar { background-color: #2b2b2b; color: #ffffff; }
QLineEdit { background-color: #2b2b2b; color: #ffffff; border: 1px solid #555555; border-radius: 4px; padding: 2px; }
QDialog { background-color: rgb(33, 33, 33); color: #ffffff; }
QRadioButton, QCheckBox { color: #ffffff; font: 10pt "Arial"; }
QMessageBox { background-color: rgb(33, 33, 33); color: #ffffff; }
QHeaderView { background-color: #353535; color: #ffffff; border: none; }
QHeaderView:horizontal { background-color: #353535; border-top-right-radius: 14px; }
QHeaderView:vertical { background-color: #353535; border-bottom-left-radius: 14px; }
QHeaderView::section { background-color: #353535; color: #ffffff; border: none; padding: 4px; font: 10pt "Arial"; }
QTableCornerButton::section { background-color: #353535; border: none; border-top-left-radius: 8px; font: 10pt "Arial"; color: rgb(255, 255, 255); }

